import {KINDS,SERMON_FORMAT,MAX_BYTES,today,clone,newEntry,parseJSON,validateJourney,validateSermon,sermonEntry,entryDraft,draftEntry,protect,unprotect,makeJourney,markdown,safeURL,validDate,validateProtected,readPackDraft} from './core.js';
import * as db from './storage.js';
import {readJournalFile} from './archive.js';
import {createSaveQueue} from './save-queue.js';
import {metadataFromSettings,importEnvelopeMetadata} from './envelope-metadata.js';
import {prepareJournalExport} from './transfer.js';
const main=document.querySelector('#main'),dialog=document.querySelector('#dialog'),picker=document.querySelector('#file-picker');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=d=>{if(!validDate(d))return d||'Undated';return new Date(d+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});};
const title=e=>e.title||'Untitled '+(KINDS[e.kind]||'entry').toLowerCase();
const splitRefs=s=>s.split(/[;\n]/).map(s=>s.trim()).filter(Boolean);
let entries=[],drafts=[],packs=[],settings=[],editor=null,packEditor=null,review=null,protectedInput=null,pickPurpose='journal',queue=Promise.resolve(),pending=0,saveError=false,toastTimer,routeSerial=0,search='',kindFilter='all',qrSVG='',currentHash=location.hash,packBase=undefined,dialogReturnFocus=null,dialogVersion=0,importReadVersion=0,storageState={supported:false,persisted:null},lastReceipt=null;
const navLabels={home:'Home',journal:'My writing',transfer:'Move to My Life With Christ',import:'Bring in notes',church:'Sermon Pack builder',guide:'How it works',privacy:'Privacy & storage',entry:'Entry',write:'Write',format:'Open format'};
function toast(message){const node=document.querySelector('#toast');node.textContent=message;node.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.hidden=true,5500);}
function errorMessage(e){return e instanceof Error?e.message:'Something went wrong. Your existing writing has not been changed.';}
function showError(e){toast(errorMessage(e));const node=document.querySelector('#form-error');if(node){node.textContent=errorMessage(e);node.focus();}}
function field(name,label,value='',type='text',hint=''){return `<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${hint?`aria-describedby="${name}-hint"`:""} ${type==='date'?'min="0001-01-01" max="9999-12-31"':''}>${hint?`<span id="${name}-hint" class="hint">${hint}</span>`:''}</div>`;}
function textarea(name,label,value='',hint='',large=false){return `<div class="field"><label for="${name}">${label}</label><div class="toolbar"><button type="button" data-action="format-text" data-field="${name}" data-format="bold" aria-label="Bold in ${label}"><b>B</b></button><button type="button" data-action="format-text" data-field="${name}" data-format="italic" aria-label="Italic in ${label}"><i>I</i></button><button type="button" data-action="format-text" data-field="${name}" data-format="list" aria-label="List in ${label}">≡</button><span>Markdown supported</span></div><textarea class="${large?'large':''}" id="${name}" name="${name}" spellcheck="true" ${hint?`aria-describedby="${name}-hint"`:""}>${esc(value)}</textarea>${hint?`<span id="${name}-hint" class="hint">${hint}</span>`:''}</div>`;}
function head(eyebrow,heading,description,action=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${heading}</h1><p class="intro">${description}</p></div>${action}</div>`;}
function newButton(){return '<a class="btn primary" href="#write/sermon">New entry <span aria-hidden="true">＋</span></a>';}
function section(label,body){return body?`<section class="detail-section"><h2>${label}</h2><div class="detail-body">${esc(body)}</div></section>`:'';}
function status(message,error=false){const el=document.querySelector('#save-status');if(el){el.textContent=message;el.classList.toggle('error',error);}}
const saver=createSaveQueue(state=>{pending=state.pending;saveError=state.failed;status(pending?'Saving on this device…':saveError?'Not saved — download your draft before leaving.':'Draft saved on this device',!pending&&saveError);},showError);
function enqueue(task){queue=saver.enqueue(task);return queue;}
async function refresh(){({entries,drafts,packs,settings}=await db.readSnapshot());entries.sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));drafts.sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));document.querySelector('#entry-count').textContent=entries.length||'';}
function breadcrumbs(page,label){const parts=[['Home','#home']];if(page==='entry'||page==='write')parts.push(['My writing','#journal']);if(page==='format')parts.push(['Sermon Pack builder','#church']);if(page!=='home')parts.push([label||navLabels[page]||'Home',null]);document.querySelector('#breadcrumbs').innerHTML=parts.map(([t,url],i)=>(i?'<span aria-hidden="true">/</span>':'')+(url&&i<parts.length-1?`<a href="${url}">${esc(t)}</a>`:`<span aria-current="page">${esc(t)}</span>`)).join('');for(const a of document.querySelectorAll('[data-nav]')){a.removeAttribute('aria-current');if(a.dataset.nav===(page==='entry'||page==='write'?'journal':page==='format'?'church':page))a.setAttribute('aria-current','page');}}
function home(){const recent=entries.slice(0,3);return `<div class="date-label">${esc(new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'}))}</div><section class="hero"><div><div class="eyebrow">YOUR WALK, REMEMBERED.</div><h1>A little space.<br><em>For what matters.</em></h1><p class="intro">The words that stayed with you. The prayer on your heart. The quiet ways God is at work. Make room to remember them.</p><div class="actions">${drafts.length?`<a class="btn primary" href="#write/draft/${encodeURIComponent(drafts[0].id)}">Continue writing</a>`:newButton()}<button class="btn" data-action="pick-sermon">Import church notes</button></div><div class="actions spaced"><a class="btn small" href="#journal">Find my writing</a><a class="btn small" href="#transfer">Move writing to the app</a><button class="btn small" data-action="backup-all">Export a full backup</button></div></div><div class="quiet-card"><blockquote>These are your words.<br>Your prayers.<br>Your story.</blockquote><small>A record to carry with you.</small></div></section><div class="section-heading"><h2>Where would you like to begin?</h2></div><div class="start-grid"><a class="start-card" href="#write/sermon"><span class="symbol" aria-hidden="true">▤</span><span class="arrow" aria-hidden="true">↗</span><h3>Start sermon notes</h3><p>Hold on to what was taught, and what it meant to you.</p></a><a class="start-card" href="#write/reading"><span class="symbol" aria-hidden="true">◫</span><span class="arrow" aria-hidden="true">↗</span><h3>Bible reading</h3><p>Keep a thought close to the Scripture that inspired it.</p></a><a class="start-card" href="#write/prayer"><span class="symbol" aria-hidden="true">✧</span><span class="arrow" aria-hidden="true">↗</span><h3>Prayer &amp; reflection</h3><p>A quiet place for what is on your heart today.</p></a></div><div class="home-bottom"><section><div class="section-heading"><h2>Pick up where you left off</h2><a href="#journal">All my writing →</a></div>${drafts.slice(0,2).map(d=>draftRow(d)).join('')}${recent.length?recent.map(e=>`<a class="recent-row" href="#entry/${encodeURIComponent(e.id)}"><strong>${esc(title(e))}</strong><small>${esc(KINDS[e.kind])} <span aria-hidden="true">·</span> ${esc(fmt(e.date))}</small></a>`).join(''):!drafts.length?'<div class="empty"><h3>Your story starts with a page.</h3><p>Your entries and unfinished drafts will appear here. Begin wherever you are.</p><a class="btn small" href="#write/reflection">Write a reflection</a></div>':''}</section><section class="panel soft church-teaser"><div class="eyebrow">FOR CHURCHES &amp; PASTORS</div><h2>Let the message<br>travel with them.</h2><p>Turn your sermon outline into notes your congregation can carry into their own journal.</p><a class="btn small" href="#church">Create a Sermon Pack <span aria-hidden="true">↗</span></a></section></div>`;}
function draftRow(d){return `<div class="draft-banner"><div><strong>${esc(d.form?.title||'Untitled draft')}</strong><small>Unfinished writing · ${esc(KINDS[d.form?.kind]||'Entry')}</small></div><a class="btn small" href="#write/draft/${encodeURIComponent(d.id)}">Continue writing</a></div>`;}
function journal(){return head('YOUR OWN WORDS','My writing','A growing record of what you heard, read, prayed, and lived.',newButton())+(lastReceipt?`<section class="notice" role="status"><h2>Import receipt</h2><p>${esc(receiptText(lastReceipt))}</p><button class="btn small" data-action="dismiss-receipt">Dismiss receipt</button></section>`:'')+(drafts.length?`<section class="draft-list"><h2>Continue a draft</h2>${drafts.map(draftRow).join('')}</section>`:'')+`<div class="filters"><div class="field"><label for="search">Find in my writing</label><input id="search" type="search" value="${esc(search)}" placeholder="A title, Scripture reference, or a word…"></div><div class="field kind-filter"><label for="kind-filter">Entry kind</label><select id="kind-filter"><option value="all">All writing</option>${Object.entries(KINDS).map(([k,v])=>`<option value="${k}" ${kindFilter===k?'selected':''}>${v}</option>`).join('')}</select></div></div><p id="search-status" role="status" aria-live="polite" aria-atomic="true">${matchingEntries().length} saved entries found.</p><div id="journal-results">${journalResults()}</div>`;}
function matchingEntries(){const q=search.toLowerCase();return entries.filter(e=>(kindFilter==='all'||e.kind===kindFilter)&&[e.title,e.notes,e.reflection,e.prayer,e.speaker,e.place,...e.scriptureRefs,...e.tags,e.sourceMaterial?.body].join(' ').toLowerCase().includes(q));}
function updateSearch(){document.querySelector('#journal-results').innerHTML=journalResults();document.querySelector('#search-status').textContent=matchingEntries().length+' saved entries found.';}
function journalResults(){const shown=matchingEntries();if(!shown.length)return `<div class="empty"><h2>${entries.length?'No entries match this search.':'There is room for your first entry.'}</h2><p>${entries.length?'Try a different word or entry kind.':'Write a few lines, or bring a journal file from your app.'}</p>${entries.length?'':newButton()}</div>`;return `<div class="entry-list">${shown.map(e=>`<article class="entry-card"><div class="entry-meta"><span class="pill">${esc(KINDS[e.kind])}</span><time datetime="${esc(e.date)}">${esc(fmt(e.date))}</time></div><h2><a href="#entry/${encodeURIComponent(e.id)}">${esc(title(e))}</a></h2><p>${esc((e.notes||e.reflection||e.prayer||e.sourceMaterial?.body||'A page in your story.').slice(0,150))}${(e.notes||e.reflection||e.prayer||'').length>150?'…':''}</p><div class="actions"><a class="btn small" href="#entry/${encodeURIComponent(e.id)}">Read entry</a><a class="btn text small" href="#write/edit/${encodeURIComponent(e.id)}">Edit</a></div></article>`).join('')}</div>`;}
function writeView(){const e=editor.entry;return head('A PAGE IN YOUR STORY',editor.base?'Continue your entry':'Put it into words.','Your notes, reflections, and prayers each have a place.')+`<div class="writing-layout"><form id="entry-form" class="writing-sheet"><p id="form-error" role="alert" tabindex="-1"></p><div class="field-grid"><div class="field"><label for="kind">What are you writing?</label><select id="kind" name="kind">${Object.entries(KINDS).map(([k,v])=>`<option value="${k}" ${e.kind===k?'selected':''}>${v}</option>`).join('')}</select></div>${field('date','Date',e.date,'date')}</div>${field('title','A title for this entry',e.title)}<details ${e.speaker||e.place||e.sermonSeries||e.scriptureRefs.length?'open':''}><summary>Scripture &amp; details</summary><div class="spaced">${field('scriptureRefs','Scripture references',e.scriptureRefs.join('; '),'text','Separate references with a semicolon, e.g. John 15:1–8; Psalm 23.')}<div class="field-grid">${field('speaker','Speaker',e.speaker)}${field('place','Church or place',e.place)}</div>${field('sermonSeries','Sermon series',e.sermonSeries)}${field('tags','Tags',e.tags.join(', '),'text','Separate tags with commas.')}</div></details><hr class="editor-divider">${e.sourceMaterial?`<details class="provided" open><summary>Provided notes${e.sourceMaterial.church?' · '+esc(e.sourceMaterial.church):''}</summary><small>Kept alongside your own writing.</small><pre>${esc(e.sourceMaterial.body)}</pre></details>`:''}${textarea('notes','My notes',e.notes,'What was taught, or what you noticed.',true)}${textarea('reflection','My reflection',e.reflection,'What this means in your own life.')}${textarea('prayer','My prayer',e.prayer,'Your words, as you choose to write them.')}<label class="check"><input type="checkbox" id="forDescendants" name="forDescendants" ${e.forDescendants?'checked':''}><span>Set this entry aside for those who come after me.</span></label><div class="savebar spaced"><span id="save-status" class="save-status" role="status" aria-live="polite" aria-atomic="true">${editor.draft?'Draft saved on this device':'Your draft will save as you write'}</span><button class="btn primary" type="submit">Save entry <span aria-hidden="true">✓</span></button></div></form><aside class="writing-aside"><div class="side-note"><div class="eyebrow">A QUIET REMINDER</div><h2>There is no perfect<br>way to begin.</h2><p>A sentence is enough. Write what you want to remember, in your own words.</p></div><div class="side-note"><h2>With you, on your device.</h2><p>Drafts save here as you write. Save your entry when you are ready to add it to your journal.</p><p>Keep a downloaded copy, too. Clearing site data can remove this writing.</p><button class="btn small" data-action="download-draft">Download this draft</button></div><div class="small-note">${e.anchors.length?'Existing Scripture and topic anchors are preserved when you save. ':''}${e.links.length?'Existing links are preserved when you save. ':''}<a href="#transfer">Move saved entries to your app →</a></div>${editor.draft?'<button class="btn text small spaced" data-action="discard-draft">Discard this draft</button>':''}</aside></div>`;}
function readEntry(id){const e=entries.find(e=>e.id===id);if(!e)return notFound();return head(esc(KINDS[e.kind]),esc(title(e)),esc(fmt(e.date)),`<a class="btn primary" href="#write/edit/${encodeURIComponent(e.id)}">Edit entry</a>`)+`<article class="writing-sheet prose"><div class="detail-context">${[e.speaker,e.place,e.sermonSeries,...e.scriptureRefs].filter(Boolean).map(esc).join(' · ')}</div>${e.sourceMaterial?`<div class="provided"><h2>Provided notes</h2><small>${esc([e.sourceMaterial.church,e.sourceMaterial.speaker].filter(Boolean).join(' · '))}</small><pre>${esc(e.sourceMaterial.body)}</pre></div>`:''}${section('My notes',e.notes)}${section('My reflection',e.reflection)}${section('My prayer',e.prayer)}${e.links.length?`<section class="detail-section"><h2>Links</h2>${e.links.map(l=>`<p>${esc(l.label||l.capturedTitle||'Saved link')}<br><span class="small-note">${esc(l.url)}</span></p>`).join('')}</section>`:''}${e.forDescendants?'<p class="small-note spaced">Set aside for those who come after you.</p>':''}<div class="actions spaced"><a class="btn" href="#transfer/${encodeURIComponent(e.id)}">Move to my app</a><button class="btn" data-action="markdown" data-id="${esc(e.id)}">Readable copy for sharing</button><button class="btn text danger" data-action="delete-entry" data-id="${esc(e.id)}">Delete entry</button></div></article>`;}
function transfer(selected){return head('YOUR WORDS GO WITH YOU','Move to My Life With Christ','Select your writing, review the file, then import it on the receiving device.')+`<div class="two-col"><section class="panel"><h2>1. Choose saved entries</h2><div class="field-grid">${field('transfer-from','From date','','date')}${field('transfer-to','Through date','','date')}</div><button class="btn small" data-action="select-dates">Select entries in this date range</button>${entries.length?`<label class="check spaced"><input type="checkbox" id="select-all" ${!selected?'checked':''}><span>Select all saved entries</span></label><div class="selection-list" tabindex="0" role="group" aria-label="Saved entries">${entries.map(e=>`<label class="check selection-row"><input type="checkbox" name="transfer-entry" value="${esc(e.id)}" ${!selected||selected===e.id?'checked':''}><span>${esc(title(e))}<small>${esc(KINDS[e.kind])} · ${esc(fmt(e.date))}</small></span></label>`).join('')}</div>`:'<p>Your saved entries will appear here.</p>'}<h2 class="spaced">2. Choose unfinished drafts separately</h2>${drafts.length?`<label class="check"><input type="checkbox" id="include-drafts"><span>Select all unfinished drafts</span></label><div class="selection-list" tabindex="0" role="group" aria-label="Unfinished drafts">${drafts.map(d=>`<label class="check selection-row"><input type="checkbox" name="transfer-draft" value="${esc(d.id)}"><span>${esc(d.form.title||'Untitled draft')}<small>Unfinished ${esc(KINDS[d.form.kind]||'entry')} · ${esc(fmt(d.form.date))}</small></span></label>`).join('')}</div>`:'<p>No unfinished drafts on this device.</p>'}<p class="notice">This full-fidelity transfer includes all content fields in each selected item, including personal reflections and prayers. Drafts stay unfinished. For a shareable copy with fewer fields, open an entry and choose “Readable copy for sharing.”</p><h2>3. Review and choose a file</h2><p class="small-note">A file supports up to 5,000 entries and 5,000 drafts, within 16 MiB for JSON or 11 MiB of journal content for a protected transfer. Split larger journals into clearly labelled selections and retain the original full archive.</p><div class="actions"><button class="btn primary" data-action="export-app" ${!entries.length&&!drafts.length?'disabled':''}>Review plain file</button><button class="btn" data-action="export-protected" ${!entries.length&&!drafts.length?'disabled':''}>Review password-protected file</button><button class="btn" data-action="export-readable" ${!entries.length?'disabled':''}>Readable selected entries</button></div><p class="small-note spaced" id="last-export">${exportStatus()}</p></section><aside class="panel soft"><h2>Finish on the receiving device</h2><ol class="steps"><li><strong>Check your download</strong>The browser offers a file. This does not confirm that it was saved or received by the app.</li><li><strong>Move the file privately</strong>iPhone/iPad: use Files or AirDrop. Android: use Downloads or a USB cable. Desktop: copy the file with a method you trust. Keep personal files out of public URLs and QR codes.</li><li><strong>Open My Life With Christ</strong>Open Your journal → Journal file to read and choose the file. Use an app build that supports protected transfers to open .lwc files. This feature is being prepared in review code and may not be in your installed build. Other builds can import plain journal JSON. OS tap/Open In and share-to-app routes are for church handouts, not this journal import. Keep your password separately.</li><li><strong>Review before importing</strong>Review duplicates and changed entries. Keep changed writing as separate copies when offered, preserving both versions.</li><li><strong>Check the import receipt</strong>The receiving app reports what it saved or skipped. Open an entry and unfinished draft there before removing any original.</li></ol><h3>Older installed app?</h3><p class="small-note">Unlock the protected file in this companion, then prepare a plain JSON transfer. The plain file is readable by anyone who has it. Compatibility with a specific phone build still needs checking.</p><a class="btn" href="#privacy">Storage &amp; backups</a></aside></div>`;}
function exportStatus(){const saved=settings.find(s=>s.id==='last-export');if(!saved)return 'No download has been recorded here. Browser storage is not a backup.';const value=saved.value,at=typeof value==='string'?value:value.at;return 'Last download offered: '+esc(new Date(at).toLocaleString())+(value?.entries!==undefined?' · '+value.entries+' entries and '+value.drafts+' drafts'+(value.metadataMaps?' and '+value.metadataMaps+' journal metadata records':''):'')+'. Saving the file and restoring an external copy have not been verified.';}
function transferReview(out){return `${out.filter?'<p class="notice">This selection excludes journal-wide metadata because it may refer to unselected private writing. Metadata within each selected entry and draft is preserved. Use a full backup to preserve the whole journal.</p>':importEnvelopeMetadata(out).length?`<p class="notice">This full journal file includes journal-wide metadata as well as the records below.</p><details class="review-card"><summary>Review all journal-wide metadata</summary><pre>${esc(JSON.stringify(importEnvelopeMetadata(out),null,2))}</pre></details>`:''}<p>${out.entries.length} saved entries · ${(out.drafts||[]).length} unfinished drafts</p><div class="selection-list">${out.entries.map(e=>`<details class="review-card"><summary>${esc(title(e))} · ${esc(fmt(e.date))}</summary>${['notes','reflection','prayer'].map(k=>e[k]?`<h3>${esc(k)}</h3><pre>${esc(e[k])}</pre>`:'').join('')}${e.sourceMaterial?`<h3>Provided notes</h3><pre>${esc(e.sourceMaterial.body)}</pre>`:''}<p class="small-note">IDs, dates, Scripture anchors, tags, provenance, and unknown fields are preserved.</p><details><summary>Full record and metadata</summary><pre>${esc(JSON.stringify(e,null,2))}</pre></details></details>`).join('')}${(out.drafts||[]).map(d=>`<details class="review-card"><summary>Unfinished: ${esc(d.form.title||'Untitled draft')}</summary>${['notes','reflection','prayer'].map(k=>d.form[k]?`<h3>${esc(k)}</h3><pre>${esc(d.form[k])}</pre>`:'').join('')}<details><summary>Full unfinished record and metadata</summary><pre>${esc(JSON.stringify(d,null,2))}</pre></details></details>`).join('')}</div>`;}
function receiptText(r){return `${r.entriesAdded} entries saved (${r.entryCopies} separate copies); ${r.entriesSkipped} entries skipped. ${r.draftsAdded} unfinished drafts saved (${r.draftCopies} separate copies); ${r.draftsSkipped} drafts skipped. Existing writing was preserved.${r.metadataMapsAdded?' '+r.metadataMapsAdded+' journal metadata records preserved.':''}`;}
function importView(){return head('MAKE ROOM FOR WHAT YOU HAVE','Bring in notes','Open a journal export, your own notes, or a church’s Sermon Pack. Review everything before saving.')+`<div class="two-col"><section><p id="form-error" role="alert" tabindex="-1"></p><div class="dropzone"><div class="symbol" aria-hidden="true">↓</div><h2>Your writing, welcomed here.</h2><p>Journal JSON or ZIP · Protected .lwc files<br>Your own plain text or Markdown notes</p><button class="btn primary" data-action="pick-journal">Choose my file</button></div><div class="panel spaced"><h2>Notes from your church?</h2><p class="small-note">A Sermon Pack goes into “Provided notes.” Your personal notes, reflection, and prayer begin empty.</p><button class="btn" data-action="pick-sermon">Import church notes</button></div>${review?reviewView():''}</section><aside class="panel soft"><h2>Always your decision.</h2><p class="small-note">Files are read on this device. You will see what was found before anything is added to your writing.</p><p class="small-note">Identical entries are skipped. If an entry has changed, you can keep the incoming version as a separate copy. Your existing entry stays intact.</p><hr class="rule"><h3>Coming from the phone app?</h3><p class="small-note">Use its exported ZIP archive, or the data/journey.json file inside it. Both carry the same journal record.</p><h3>Have a PDF or Word document?</h3><p class="small-note">Use the installed app’s document importer for those formats. This companion currently opens text, Markdown, structured sermon notes, and journal files.</p></aside></div>`;}
function reviewView(){if(review.type==='pack-draft')return `<section class="panel spaced" id="import-review"><h2>Restore this church draft?</h2><h3>${esc(review.raw.title||'Untitled church draft')}</h3><p>This creates a separate draft in the Sermon Pack builder. Your personal journal and existing outlines remain unchanged. Only supported public v1 fields are restored; unknown file fields are excluded.</p><details open><summary>Review restored outline and fields</summary><pre>${esc(JSON.stringify(review.raw,null,2))}</pre></details><p>An unfinished outline can be recovered here. It must pass validation before you download a publishable Sermon Pack.</p><div class="actions"><button class="btn primary" data-action="confirm-pack-draft">Restore as a new church draft</button><button class="btn" data-action="cancel-import">Cancel</button></div></section>`;if(review.type==='sermon')return `<section class="panel spaced" id="import-review"><span class="pill gold">PROVIDED NOTES</span><h2 class="spaced">${esc(review.raw.title||'Sermon notes')}</h2><p class="small-note">${esc([review.raw.church,review.raw.speaker,review.raw.date].filter(Boolean).join(' · '))}</p><div class="review-card"><pre>${esc(review.raw.bodyMarkdown)}</pre></div><p class="small-note">The church and speaker names are claims in the file, not verified identities. This will start a new draft. Your own notes, reflection, and prayer will be empty.</p><div class="actions"><button class="btn primary" data-action="confirm-sermon">Start my entry with these notes</button><button class="btn" data-action="cancel-import">Cancel</button></div></section>`;const draftPlan=db.planStoredImport(review.journey.drafts||[],drafts,'drafts'),draftChanges=draftPlan.filter(p=>p.status==='conflict').length;const plan=db.planStoredImport(review.journey.entries,entries),n=plan.filter(p=>p.status==='new').length,c=plan.filter(p=>p.status==='conflict').length,du=plan.filter(p=>p.status==='duplicate').length;return `<section class="panel spaced" id="import-review"><div class="eyebrow">REVIEW BEFORE ADDING</div><h2>${review.journey.entries.length} entr${review.journey.entries.length===1?'y':'ies'} found</h2><p class="small-note">${n} new · ${du} identical · ${c} changed · ${(review.journey.drafts||[]).length} unfinished drafts</p>${review.journey.filter?'<div class="notice">This file is a partial journal export.</div>':''}${importEnvelopeMetadata(review.journey).length?`<details class="review-card"><summary>${importEnvelopeMetadata(review.journey).length} journal metadata records will be preserved</summary><pre>${esc(JSON.stringify(importEnvelopeMetadata(review.journey),null,2))}</pre></details>`:''}<div class="selection-list" tabindex="0" role="group" aria-label="Entry import review">${plan.map(p=>`<div class="review-card"><span class="pill">${p.status==='conflict'?'Changed entry':p.status==='duplicate'?'Already here':'New entry'}</span><h3 class="spaced">${esc(title(p.entry))}</h3><p class="small-note">${esc(fmt(p.entry.date))}</p><details><summary>Review all entry fields</summary><pre>${esc(JSON.stringify(p.entry,null,2))}</pre></details></div>`).join('')}</div>${draftPlan.map(p=>`<div class="review-card"><span class="pill">Unfinished draft · ${p.status==='duplicate'?'Already here':p.status==='conflict'?'Changed draft':'New draft'}</span><h3>${esc(p.entry.form.title||'Untitled draft')}</h3><details><summary>Review all unfinished draft fields</summary><pre>${esc(JSON.stringify(p.entry,null,2))}</pre></details></div>`).join('')}${c||draftChanges?'<label class="check"><input type="checkbox" id="keep-copies" checked><span>Keep changed entries and drafts as separate copies, preserving both versions.</span></label>':''}<div class="actions spaced"><button class="btn primary" data-action="confirm-import">Add to my writing</button><button class="btn" data-action="cancel-import">Cancel</button></div></section>`;}
function packListContent(){return `<h2>Your pack drafts</h2>${packs.filter(p=>!p.template).map(p=>`<div class="pack-row"><strong>${esc(p.value.title||'Untitled Sermon Pack')}</strong><div class="actions"><button class="btn small" data-action="open-pack" data-id="${esc(p.id)}">Open</button><button class="btn small" data-action="delete-pack" data-id="${esc(p.id)}">Delete</button></div></div>`).join('')||'<p>No saved pack drafts yet. Start your outline above.</p>'}<div class="actions spaced"><button class="btn small" data-action="new-pack">Start another pack</button><button class="btn small" data-action="pick-pack-draft">Restore a church draft file</button></div><h2 class="spaced">Reusable templates</h2>${packs.filter(p=>p.template).map(p=>`<div class="pack-row"><strong>${esc(p.value.title||'Untitled template')}</strong><div class="actions"><button class="btn small" data-action="use-template" data-id="${esc(p.id)}">Use as new draft</button><button class="btn small" data-action="delete-pack" data-id="${esc(p.id)}">Delete</button></div></div>`).join('')||'<p>Save an outline as a template, then use a fresh copy each week.</p>'}`;}
function churchView(){const p=packEditor?.value||{format:SERMON_FORMAT,version:1,title:'',church:'',speaker:'',date:today(),scripture:[],bodyMarkdown:''};return head('FOR CHURCHES & PASTORS','Let the message travel.','Prepare an outline, preview what people receive, then publish the file on your church’s own website.')+`<div class="writing-layout"><div><form id="pack-form" class="writing-sheet"><p id="form-error" role="alert" tabindex="-1"></p>${field('pack-title','Sermon title',p.title)}<div class="field-grid">${field('pack-church','Church',p.church)}${field('pack-speaker','Speaker',p.speaker)}</div><div class="field-grid">${field('pack-date','Sermon date',p.date,'date')}${field('pack-scripture','Scripture references',(p.scripture||[]).join('; '),'text','Separate references with semicolons.')}</div>${textarea('pack-body','Provided notes',p.bodyMarkdown,'Add your outline, questions, and reuse permission. Use Scripture references for Bible passages.',true)}<div class="savebar"><span id="save-status" class="save-status" role="status" aria-live="polite" aria-atomic="true">${packEditor?'Pack draft saved on this device':'Your pack draft saves on this device'}</span><div class="actions"><button class="btn" data-action="preview-pack" type="button">Preview recipient’s notes</button><button class="btn primary" type="submit">Download Sermon Pack ↓</button></div></div><div class="actions spaced"><button class="btn small" data-action="save-template" type="button">Save reusable template</button><button class="btn small" data-action="download-pack-draft" type="button">Download draft recovery copy</button></div><p class="small-note spaced">Drafts and templates are stored separately from your personal journal. A journal backup does not include pastor drafts. Download a recovery copy of each outline you want to preserve.</p></form><section class="pack-list" id="pack-list">${packListContent()}</section></div><aside><div class="side-note"><h2>One outline.<br>Many personal stories.</h2><p>Your notes arrive under “Provided notes.” A reader’s own notes, reflection, and prayer begin empty.</p><p>Share only material your church has permission to distribute. A church name in a file is not verified identity.</p><div class="actions"><a class="btn small" href="publishing-guide.md" download>Download publishing guide</a><a class="btn small" href="example-sermon-notes.json" download>Download fictional example</a></div><a href="#format">Read the open format →</a></div><section class="panel"><div class="eyebrow">A QR FOR YOUR BULLETIN</div><h2>Make it easy to find.</h2><p class="small-note">Download the pack and upload it to your church website. Paste its existing public HTTPS file URL below. This generator does not upload the file or verify that the URL works.</p>${field('pack-url','Public pack download link','','url','Use only public church material, never a personal journal link.')}<button class="btn" data-action="make-qr">Create QR code</button><p id="qr-status" role="status" aria-live="polite" aria-atomic="true"></p><div id="qr-result"></div></section></aside></div>`;}
function guide(){return head('A SIMPLE COMPANION','Write here. Carry it with you.','A comfortable place for longer writing, connected to the journal you keep in My Life With Christ.')+`<div class="prose"><h2>For your own writing</h2><ol class="steps"><li><strong>Start a page</strong>Choose sermon, Bible reading, prayer, reflection, or letter. Drafts save on this device as you write.</li><li><strong>Save it to your writing</strong>When you are ready, choose Save entry. Your provided notes, personal notes, reflection, and prayer stay in separate fields.</li><li><strong>Take it into your app</strong>Move to my app creates the journal JSON format the existing app imports. Transfer it to your phone, then preview and merge in the app.</li></ol><h2>For churches and pastors</h2><p>The <a href="#church">Sermon Pack builder</a> creates the version 1 sermon-notes file already supported by My Life With Christ. Place the downloaded file on your church website and make a QR code for that link. A reader downloads the file and opens it with the app’s provided-notes importer.</p><p>A church pack includes the sermon title, church, speaker, date, Scripture references, and provided notes. This edition is a text format; it does not embed PDF attachments.</p><h2>Files you can keep</h2><table class="format-table"><thead><tr><th>File</th><th>Open it with</th><th>What it contains</th></tr></thead><tbody><tr><td>Journal .json</td><td>The app or this companion</td><td>Selected entries and optional drafts, readable as text. Unencrypted.</td></tr><tr><td>Protected .lwc</td><td>This companion or a compatible updated app + your password</td><td>An encrypted journal transfer. Updated app builds can unlock it; older builds use the companion to unlock and export plain JSON.</td></tr><tr><td>Sermon Pack .json</td><td>The app’s provided-notes importer or this companion</td><td>Church material intended for distribution. Unencrypted.</td></tr><tr><td>Readable .md</td><td>Any text editor</td><td>One entry with clearly labelled sections.</td></tr></tbody></table><h2>A companion, with a clear purpose</h2><p>Your browser and phone each keep their own copy. Moving a file is a deliberate transfer. After editing on both devices, review the versions before merging. This edition does not automatically synchronize them.</p><p><a href="#privacy">Learn about device storage and privacy →</a></p></div>`;}
function privacy(){const request=settings.find(s=>s.id==='persistence-request')?.value;return head('YOUR WORDS STAY WITH YOU','Storage &amp; backups','A public website. Your writing saved in this browser, on this device.')+`<div class="prose"><section class="panel"><h2>On this device</h2><p>${entries.length} saved entries · ${drafts.length} unfinished drafts · ${packs.filter(p=>!p.template).length} church pack drafts · ${packs.filter(p=>p.template).length} templates · ${metadataFromSettings(settings).length} journal metadata records</p><p>These live in this browser’s IndexedDB. A different browser, profile, device, or domain has separate storage. Browser storage is not a backup.</p><p id="persistence-result" role="status" aria-live="polite">Checking the browser’s persistent-storage report…</p><button class="btn" data-action="request-persistence">Request persistent storage</button><p class="small-note spaced">${request?'Last request recorded here: '+esc(new Date(request.at).toLocaleString())+'. The browser reported '+(request.granted?'granted':'not granted')+'.':'No persistent-storage request has been recorded here. Status may have changed outside this companion.'}</p></section><section class="spaced"><h2>Keep a portable backup</h2><p>${exportStatus()}</p><p>A full journal backup keeps entries, drafts, metadata, and every personal field. Keep it in a safe place. A readable sharing copy may omit fields and cannot replace that backup. Pastor pack drafts and templates are separate: download recovery copies in the builder.</p><div class="actions"><button class="btn primary" data-action="backup-all">Review full journal backup</button><a class="btn" href="#transfer">Choose entries and dates</a><a class="btn" href="#import">Restore a journal file</a></div><ol class="steps spaced"><li><strong>Export and check the file</strong>Confirm the download exists. For protected transfers, keep the password separately.</li><li><strong>Test in an isolated browser profile</strong>Import into an empty companion profile or test journal. Review the receipt and compare entries, drafts, and metadata before trusting the backup.</li><li><strong>Keep the original</strong>Restoring adds new items and skips duplicates. Changed items can become separate copies. It does not replace your existing journal.</li></ol><p>For the enduring <strong>My Journey With Christ</strong> archive and printable book, import this journal into the installed app and use its preservation/export tools. The companion’s plain JSON remains the app’s established transfer format.</p></section><h2>Privacy and encryption</h2><p>This companion does not upload writing. It has no analytics, external fonts, account system, or background synchronization. The host receives the usual requests needed to serve the website.</p><p>Local writing is not encrypted at rest. Someone with access to this unlocked browser profile may be able to read it. Native App Lock is an access control and is separate from backup encryption or synchronization.</p><p>A protected .lwc file uses your password locally. There is no password recovery. Encryption does not protect copies already unlocked or an untrusted device, and this implementation has not had an independent security review. Plain journal JSON and readable copies are unencrypted.</p><h2>If a save fails</h2><p>Keep this tab open. Download the current draft recovery copy before leaving or reloading. A local-save message confirms an IndexedDB transaction completed, not that another device received anything. Full storage and browser data clearing can cause loss without an external copy.</p><h2>Offline and changing domains</h2><p>An already loaded page can keep writing while offline, but this edition has no offline installation or service worker. Reloading offline is not guaranteed. Download a backup before updating or moving to another address.</p><p>A proposed move to journal.prayersealed.org does not move browser data automatically. Export from the old address, import and verify at the new address, and keep access to the old site until that check succeeds. No new domain is claimed live here.</p><h2>Church QR codes</h2><p>QR codes contain only the public church-file URL you enter. They do not publish or upload anything. Never put private writing in a URL or QR code.</p></div>`;}
function formatView(){return head('OPEN & PORTABLE','The Sermon Pack format','A simple format a church can create and a reader can keep.')+`<div class="prose"><p>The current app already recognizes <code>my-life-with-christ-sermon-notes</code>, version <code>1</code>. This companion uses that exact format. “Sermon Pack” is the friendly name for a plain JSON file.</p><table class="format-table"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>format</code></td><td>Exactly <code>my-life-with-christ-sermon-notes</code></td></tr><tr><td><code>version</code></td><td>1</td></tr><tr><td><code>bodyMarkdown</code></td><td>Required, nonempty notes; up to 200,000 characters.</td></tr><tr><td><code>title, church, speaker</code></td><td>Optional plain text.</td></tr><tr><td><code>date</code></td><td>Optional YYYY-MM-DD calendar date.</td></tr><tr><td><code>scripture</code></td><td>Optional array of Scripture reference strings.</td></tr></tbody></table><p>The installed app accepts sermon files up to 8 MB. Unknown fields are ignored there; attachments, package identifiers, and revision tracking are not part of this version. Put permission or attribution wording in the provided notes so it travels visibly with the text.</p><div class="actions"><a class="btn primary" href="sermon-notes-format.md" download>Download the specification</a><a class="btn" href="example-sermon-notes.json" download>Download an example</a></div><h2>For church website developers</h2><p>Serve the JSON file over HTTPS with a stable download URL. A QR can link directly to that file. No account, callback, tracking pixel, or proprietary server is required. The reader explicitly chooses when to import it.</p><p>Provided notes always remain distinct from a person’s own notes, reflection, and prayer.</p><a class="btn" href="#church">Open the builder →</a></div>`;}
function notFound(){return head('A PAGE TO FIND','This entry is not here.','It may be saved on a different device or in another browser.')+'<a class="btn primary" href="#journal">Back to my writing</a>';}
async function route(){const serial=++routeSerial;await saver.settledRead(refresh);if(serial!==routeSerial)return;if(saveError&&(editor||packEditor)){window.history.replaceState(null,'',currentHash||'#home');toast('Your latest writing could not be saved. Download a copy before leaving this page.');return;}const [page='home',a,b]=(location.hash.slice(1)||'home').split('/').map(s=>decodeURIComponent(s));editor=null;let html;if(page==='write'){
 let e,d,base;if(a==='edit'){base=entries.find(e=>e.id===b);if(!base){main.innerHTML=notFound();return;}d=drafts.find(d=>d.entryId===base.id);e=d?draftEntry(d):clone(base);}else if(a==='draft'){d=drafts.find(d=>d.id===b);if(!d){main.innerHTML=notFound();return;}e=draftEntry(d);base=d.entryId?entries.find(e=>e.id===d.entryId):undefined;}else e=newEntry(a);
 editor={entry:e,draft:d,persistedDraft:d?clone(d):undefined,base:base?clone(base):undefined};html=writeView();
 }else if(page==='entry')html=readEntry(a);else if(page==='journal')html=journal();else if(page==='transfer')html=transfer(a);else if(page==='import')html=importView();else if(page==='church'){if(!packEditor&&packs.some(p=>!p.template)){packEditor=clone(packs.find(p=>!p.template));packBase=clone(packEditor);}html=churchView();}else if(page==='guide')html=guide();else if(page==='privacy')html=privacy();else if(page==='format')html=formatView();else html=home();
 if(serial!==routeSerial)return;main.innerHTML=html;currentHash=location.hash;breadcrumbs(page,page==='entry'?title(entries.find(e=>e.id===a)||{}):undefined);document.title=(navLabels[page]||'Home')+' · My Life With Christ';main.focus({preventScroll:true});if(page==='write')document.querySelector('#notes')?.focus({preventScroll:true});if(page==='privacy')await refreshStorageStatus();window.scrollTo?.(0,0);
}
function collectEntry(){const form=document.querySelector('#entry-form');if(!form||!editor)return;const f=new FormData(form),e=editor.entry;for(const k of ['kind','title','date','place','speaker','sermonSeries','notes','reflection','prayer'])e[k]=String(f.get(k)||'');e.scriptureRefs=splitRefs(String(f.get('scriptureRefs')||''));e.tags=String(f.get('tags')||'').split(',').map(s=>s.trim()).filter(Boolean);e.forDescendants=f.has('forDescendants');}
function persistDraft(){collectEntry();const d=entryDraft(editor.entry,editor.draft);if(editor.base)d.entryId=editor.base.id;editor.draft=d;const snap=clone(d),session=editor;enqueue(async()=>{await db.putDraft(snap,session.persistedDraft);session.persistedDraft=snap;});}
function collectPack(){const form=document.querySelector('#pack-form');if(!form)return null;const f=new FormData(form);return {format:SERMON_FORMAT,version:1,title:String(f.get('pack-title')||''),church:String(f.get('pack-church')||''),speaker:String(f.get('pack-speaker')||''),date:String(f.get('pack-date')||''),scripture:splitRefs(String(f.get('pack-scripture')||'')),bodyMarkdown:String(f.get('pack-body')||'')};}
function persistPack(){const value=collectPack();if(!value)return;if(!packEditor)packEditor={id:crypto.randomUUID()};Object.assign(packEditor,{value,updatedAt:new Date().toISOString()});const snap=clone(packEditor),session=packEditor;enqueue(async()=>{await db.putPack(snap,packBase);if(packEditor===session)packBase=snap;packs=packs.filter(p=>p.id!==snap.id).concat(clone(snap));const list=document.querySelector('#pack-list');if(list)list.innerHTML=packListContent();});}
function download(name,data,type='application/json'){const blob=new Blob([typeof data==='string'||data instanceof Uint8Array?data:JSON.stringify(data,null,2)],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),15000);}
function fileStem(s){return s.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,65)||'sermon-notes';}
function closeDialog(){dialogVersion++;dialog.close();document.querySelector('#dialog-body').replaceChildren();protectedInput=null;dialogReturnFocus?.isConnected&&dialogReturnFocus.focus();}
function modal(html){dialogVersion++;dialogReturnFocus=document.activeElement;document.querySelector('#dialog-body').innerHTML=html;const heading=dialog.querySelector('h2');if(heading){heading.id='dialog-heading';heading.tabIndex=-1;dialog.setAttribute('aria-labelledby','dialog-heading');}dialog.showModal();(dialog.querySelector('input[type=password]')||heading||dialog.querySelector('input,button'))?.focus();}
async function confirmAction(heading,text,action){modal(`<h2>${heading}</h2><p>${text}</p><div class="dialog-actions"><button class="btn" data-dialog="cancel">Keep it</button><button class="btn danger" data-dialog="confirm">Delete</button></div>`);dialog.querySelector('[data-dialog="confirm"]').onclick=async()=>{try{await action();closeDialog();await route();}catch(e){showError(e);}};}
function selectedJourney(){const selected=[...document.querySelectorAll('[name="transfer-entry"]:checked')].map(c=>c.value),selectedDrafts=[...document.querySelectorAll('[name="transfer-draft"]:checked')].map(c=>c.value);return journeyWithMetadata(entries.filter(e=>selected.includes(e.id)),drafts.filter(d=>selectedDrafts.includes(d.id)));}
function journeyWithMetadata(es,ds,allowEmpty=false){return prepareJournalExport(es,ds,{totalEntries:entries.length,totalDrafts:drafts.length,metadata:metadataFromSettings(settings),allowEmpty});}

async function recordExport(out,method){const value={at:new Date().toISOString(),method,stage:'offered-to-browser',entries:out.entries.length,drafts:(out.drafts||[]).length,metadataMaps:importEnvelopeMetadata(out).length};try{await db.put('settings',{id:'last-export',value});settings=settings.filter(s=>s.id!=='last-export').concat({id:'last-export',value});const line=document.querySelector('#last-export');if(line)line.textContent=exportStatus();return true;}catch{toast('The browser was offered your file, but its download record could not be saved. Check the file yourself.');return false;}}
function dialogIsCurrent(version,form){return version===dialogVersion&&dialog.open&&form.isConnected&&dialog.contains(form);}
function offerTransfer(out,protectedFile=false){
 if(protectedFile){modal(`<h2>Review password-protected transfer</h2>${transferReview(out)}<p>Use a strong password of at least 12 characters. Keep it separately; there is no password recovery. Your selected private fields are included.</p><form id="protect-form">${field('protect-password','Password','','password')}${field('protect-again','Confirm password','','password')}<p id="protect-error" role="alert"></p><div class="dialog-actions"><button class="btn" type="button" data-dialog="cancel">Cancel</button><button class="btn primary" type="submit">Protect &amp; offer download</button></div></form>`);document.querySelector('#protect-form').onsubmit=async e=>{e.preventDefault();const btn=e.submitter,form=e.target,version=dialogVersion;btn.disabled=true;try{let pass=form.querySelector('#protect-password').value;if(pass!==form.querySelector('#protect-again').value)throw Error('The passwords do not match.');const encrypted=await protect(out,pass);pass='';if(!dialogIsCurrent(version,form))return;form.querySelector('#protect-password').value='';form.querySelector('#protect-again').value='';download('my-writing-'+today()+'.lwc',encrypted);closeDialog();if(await recordExport(out,'protected'))toast('Protected file offered to your browser. Check it saved; the app has not confirmed receipt.');}catch(err){if(!dialogIsCurrent(version,form))return;form.querySelector('#protect-error').textContent=errorMessage(err);btn.disabled=false;}};return;}
 modal(`<h2>Review plain journal file</h2>${transferReview(out)}<p>This file contains the selected notes, reflections, prayers, and provided notes. Anyone who has it can read them. Use a private file-transfer method.</p><div class="dialog-actions"><button class="btn" data-dialog="cancel">Cancel</button><button class="btn primary" id="download-confirm">Offer journal download</button></div>`);document.querySelector('#download-confirm').onclick=async()=>{download('journey-export-'+today()+'.json',out);closeDialog();if(await recordExport(out,'plain-json'))toast('Journal file offered to your browser. Check it saved; the app has not confirmed receipt.');};
}
function sharingOptions(value){const selected=Array.isArray(value)?value:[value];if(!selected.length)throw Error('Choose at least one saved entry for a readable copy. Unfinished drafts remain in journal backups.');modal(`<h2>Readable copy for sharing</h2><p>${selected.length} saved entr${selected.length===1?'y':'ies'} selected. Unfinished drafts are excluded.</p><p>Your personal notes and the selected provided material are readable by whoever receives the file. Reflections and prayers start excluded. This is a readable copy, not a full-fidelity backup.</p><label class="check"><input id="share-provided" type="checkbox" checked><span>Include provided notes</span></label><label class="check"><input id="share-reflection" type="checkbox"><span>Include my personal reflection</span></label><label class="check"><input id="share-prayer" type="checkbox"><span>Include my personal prayer</span></label><h3 class="spaced">Preview of this copy</h3><pre class="preview-body" id="share-preview"></pre><div class="dialog-actions"><button class="btn" data-dialog="cancel">Cancel</button><button class="btn primary" id="share-download">Download selected fields</button></div>`);const content=()=>selected.map(e=>markdown(e,{provided:document.querySelector('#share-provided').checked,reflection:document.querySelector('#share-reflection').checked,prayer:document.querySelector('#share-prayer').checked})).join('\n\n---\n\n');const preview=()=>document.querySelector('#share-preview').textContent=content();dialog.querySelectorAll('input').forEach(el=>el.addEventListener('change',preview));preview();document.querySelector('#share-download').onclick=()=>{download((selected.length===1?fileStem(title(selected[0])):'selected-writing-'+today())+'.md',content(),'text/markdown');closeDialog();toast('Readable copy offered to your browser. Only the selected fields were included.');};}
async function refreshStorageStatus(){storageState.supported=!!navigator.storage?.persisted;storageState.failed=false;try{storageState.persisted=storageState.supported?await navigator.storage.persisted():null;}catch{storageState.persisted=null;storageState.failed=true;}const node=document.querySelector('#persistence-result');if(node)node.textContent=storageState.failed?'The browser’s persistent-storage check failed. Try again later and keep downloaded backups.':storageState.persisted===true?'This browser reports persistent storage is granted. It is still not an external backup.':storageState.persisted===false?'This browser reports persistent storage is not granted. Keep downloaded backups.':'This browser cannot report persistent-storage status. Keep downloaded backups.';}
async function openFile(file,version){if(!file)return;if(file.size>MAX_BYTES)throw Error('Choose a file smaller than 16 MB.');const bytes=new Uint8Array(await file.arrayBuffer()),isZip=bytes[0]===0x50&&bytes[1]===0x4b;if(version!==importReadVersion)return;let raw,nextReview;if(!isZip&&!/\.(txt|md)$/i.test(file.name))raw=parseJSON(new TextDecoder('utf-8',{fatal:true}).decode(bytes));
 if(pickPurpose==='pack-draft'){nextReview={type:'pack-draft',raw:readPackDraft(raw)};if(version!==importReadVersion)return;review=nextReview;if(location.hash!=='#import')location.hash='#import';else await route();return;}
 if(raw?.format==='lwc-companion-protected'){validateProtected(raw);protectedInput=raw;modal(`<h2>Unlock your writing</h2><p>This file is unlocked on this device. Your password is never saved.</p><form id="unlock-form">${field('unlock-password','File password','','password')}<p id="unlock-error" class="small-note" role="alert"></p><div class="dialog-actions"><button type="button" class="btn" data-dialog="cancel">Cancel</button><button class="btn primary" type="submit">Unlock file</button></div></form>`);return;}
 if(raw?.format===SERMON_FORMAT){validateSermon(raw);nextReview={type:'sermon',raw,filename:file.name,bytes};}else if(pickPurpose==='sermon'){throw Error('Choose the church’s sermon-notes JSON file.');}else if(/\.(txt|md)$/i.test(file.name)){const text=new TextDecoder('utf-8',{fatal:true}).decode(bytes);if(!text.trim())throw Error('This note is empty.');const e=newEntry('reflection');e.title=file.name.replace(/\.(txt|md)$/i,'');e.notes=text;e.source={filename:file.name,format:/\.md$/i.test(file.name)?'markdown':'txt',importedAt:new Date().toISOString(),itemIndex:1,parserVersion:1};nextReview={type:'journal',journey:makeJourney([e])};}else{nextReview={type:'journal',journey:isZip?await readJournalFile(bytes):validateJourney(raw)};}
 if(version!==importReadVersion)return;review=nextReview;
 if(location.hash!=='#import')location.hash='#import';else await route();document.querySelector('#import-review')?.scrollIntoView?.({block:'start'});
}
main.addEventListener('input',e=>{if(e.target.closest('#entry-form'))persistDraft();else if(e.target.closest('#pack-form'))persistPack();else if(e.target.id==='search'){search=e.target.value;updateSearch();}});
