main.addEventListener('submit',async event=>{event.preventDefault();const button=event.submitter;try{button&&(button.disabled=true);if(event.target.id==='entry-form'){collectEntry();if(!validDate(editor.entry.date))throw Error('Choose a real date before saving.');if(![editor.entry.title,editor.entry.notes,editor.entry.reflection,editor.entry.prayer,editor.entry.sourceMaterial?.body].some(s=>s?.trim()))throw Error('Write something before saving this entry.');await saver.settle();const saved={...clone(editor.entry),updatedAt:new Date().toISOString()};await db.saveEntry(saved,editor.draft?.id,editor.base,editor.persistedDraft);saveError=false;toast('Entry saved on this device.');location.hash='#entry/'+encodeURIComponent(saved.id);}else if(event.target.id==='pack-form'){persistPack();await saver.settle();const value=validateSermon(collectPack());download(fileStem(value.title)+'.sermon-notes.json',value);toast('Sermon Pack download prepared.');}}catch(e){showError(e);}finally{if(button)button.disabled=false;}});
