 if(action==='format-text'){const el=document.getElementById(b.dataset.field),a=el.selectionStart,z=el.selectionEnd,text=el.value.slice(a,z),type=b.dataset.format;const replacement=type==='list'?'- '+(text||''):type==='bold'?'**'+text+'**':'*'+text+'*';el.setRangeText(replacement,a,z,'select');el.dispatchEvent(new Event('input',{bubbles:true}));el.focus();}
