 if(action==='discard-draft')await confirmAction('Discard this draft?','This removes only the unfinished draft. Any saved entry remains.',async()=>{await db.remove('drafts',editor.draft.id);location.hash='#journal';});
 if(action==='markdown')sharingOptions(entries.find(e=>e.id===b.dataset.id));
 if(action==='delete-entry')await confirmAction('Delete this entry?','This removes the saved entry on this device. Download a copy first if you want to keep it.',async()=>{await db.remove('entries',b.dataset.id);location.hash='#journal';});
 if(action==='pick-journal'||action==='pick-sermon'||action==='pick-pack-draft'){pickPurpose=action==='pick-sermon'?'sermon':action==='pick-pack-draft'?'pack-draft':'journal';picker.accept=pickPurpose==='journal'?'.json,.lwc,.zip,.txt,.md':'.json';picker.value='';picker.click();}
 if(action==='cancel-import'){importReadVersion++;review=null;await route();}
 if(action==='confirm-pack-draft'){b.disabled=true;const restored={id:crypto.randomUUID(),value:clone(review.raw),updatedAt:new Date().toISOString()};await db.putPack(restored,undefined);packEditor=restored;packBase=clone(restored);review=null;location.hash='#church';toast('Church draft restored as a separate outline on this device. Validate it before publishing.');}
 if(action==='confirm-sermon'){b.disabled=true;const e=await sermonEntry(review.raw,review.filename,review.bytes),d=entryDraft(e);await db.put('drafts',d);review=null;location.hash='#write/draft/'+encodeURIComponent(d.id);toast('Provided notes added to a new draft.');}
 if(action==='confirm-import'){b.disabled=true;lastReceipt=await db.importJourney(review.journey,document.querySelector('#keep-copies')?.checked!==false);review=null;location.hash='#journal';toast(receiptText(lastReceipt));}
 if(action==='export-app')offerTransfer(selectedJourney());
