 if(action==='export-protected')offerTransfer(selectedJourney(),true);
 if(action==='backup-all'){await saver.settledRead(refresh);offerTransfer(journeyWithMetadata(entries,drafts,true));}
 if(action==='dismiss-receipt'){lastReceipt=null;await route();}
 if(action==='select-dates'){const from=document.querySelector('#transfer-from').value,to=document.querySelector('#transfer-to').value;if(from&&!validDate(from)||to&&!validDate(to)||from&&to&&from>to)throw Error('Choose a valid date range, with the start before the end.');for(const c of document.querySelectorAll('[name="transfer-entry"]')){const e=entries.find(e=>e.id===c.value);c.checked=(!from||e.date>=from)&&(!to||e.date<=to);}document.querySelector('#select-all')&&(document.querySelector('#select-all').checked=[...document.querySelectorAll('[name="transfer-entry"]')].every(c=>c.checked));toast('Saved entry selection updated. Unfinished draft choices are unchanged.');}
 if(action==='preview-pack'){const value=validateSermon(collectPack());modal(`<div class="eyebrow">PROVIDED NOTES PREVIEW</div><h2>${esc(value.title||'Sermon notes')}</h2><p>${esc([value.church,value.speaker,value.date].filter(Boolean).join(' · '))}</p><p>${esc(value.scripture.join('; '))}</p><div class="preview-body">${esc(value.bodyMarkdown)}</div><div class="dialog-actions"><button class="btn" data-dialog="cancel">Back to editing</button></div>`);}
 if(action==='new-pack'){await saver.settle();if(saveError)throw Error('Download your current pack draft before starting another.');packEditor=null;packBase=undefined;main.innerHTML=churchView();document.querySelector('#pack-title').focus();}
 if(action==='open-pack'){await saver.settle();if(saveError)throw Error('Download your current pack draft before opening another.');packEditor=clone(packs.find(p=>p.id===b.dataset.id));packBase=clone(packEditor);await route();}
 if(action==='delete-pack')await confirmAction('Delete this pack draft?','Downloaded copies and your personal journal remain unchanged.',async()=>{await db.remove('packs',b.dataset.id);if(packEditor?.id===b.dataset.id){packEditor=null;packBase=undefined;}});
 if(action==='download-pack-draft'){const value=collectPack();download(fileStem(value.title)+'-draft.json',value);toast('Draft recovery copy offered to your browser. Validate its outline before publishing; an incomplete draft may not import as a Sermon Pack.');}
 if(action==='save-template'){const value=validateSermon(collectPack());const template={id:crypto.randomUUID(),template:true,value:clone(value),updatedAt:new Date().toISOString()};await db.putPack(template,undefined);await refresh();toast('Reusable template saved on this device. Your current draft is unchanged.');await route();}
 if(action==='use-template'){await saver.settle();if(saveError)throw Error('Download your current pack draft before using a template.');const template=packs.find(p=>p.id===b.dataset.id);packEditor={id:crypto.randomUUID(),value:{...clone(template.value),date:today()},updatedAt:new Date().toISOString()};await db.putPack(packEditor,undefined);packBase=clone(packEditor);await route();document.querySelector('#pack-title').focus();toast('A new draft was created. The reusable template is unchanged.');}
 if(action==='make-qr'){const url=safeURL(document.querySelector('#pack-url').value);if(url.length>1500)throw Error('Use a shorter public download link.');const qr=window.qrcode(0,'M');qr.addData(url,'Byte');qr.make();qrSVG=qr.createSvgTag({cellSize:5,margin:20,scalable:true});document.querySelector('#qr-result').innerHTML=`<div class="qr" role="img" aria-label="QR code for the church download link">${qrSVG}</div><p class="small-note">Links to: ${esc(url)}<br>Open and test this link before printing your bulletin.</p><button class="btn small" data-action="download-qr">Download QR image</button>`;document.querySelector('#qr-status').textContent='QR code prepared for the public link shown below. No file was uploaded or published.';}
 if(action==='download-qr')download('sermon-pack-qr.svg',qrSVG,'image/svg+xml');
